output_text:
[
  {
    "id": "no_cart_single_file_aisle",
    "text": "Shopping carts are prohibited in single-file aisles, distinguished by a horizontal free width of one cell.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartInSingleFileAisle": {
          "and": [
            "hasCart",
            "singleFileAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartInSingleFileAisle"
    }
  },
  {
    "id": "no_cart_between_facing_shelves",
    "text": "Carts may not be taken into aisles where shelves face the agent on both the east and west sides.",
    "abstraction": {
      "state_properties": {
        "betweenFacingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "cartBetweenFacingShelves": {
          "and": [
            "hasCart",
            "betweenFacingShelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartBetweenFacingShelves"
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "An agent must not move into a single-file aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "cartMovesIntoSingleFileAisle": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartMovesIntoSingleFileAisle"
    }
  },
  {
    "id": "park_at_pedestrian_aisle_mouth",
    "text": "Upon arriving with a cart at the mouth of the pedestrian-only aisle, the agent is obliged to park the cart there before proceeding.",
    "abstraction": {
      "state_properties": {
        "pedestrianAisleMouth": "at(6,3)",
        "wideMouth": {
          "and": [
            "pedestrianAisleMouth",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "arriveAtPedestrianAisleMouthWithCart": {
          "pre": "MOVE",
          "post": {
            "and": [
              "wideMouth",
              "hasCart"
            ]
          }
        },
        "parkCartAtPedestrianAisleMouth": {
          "pre": {
            "and": [
              "wideMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arriveAtPedestrianAisleMouthWithCart",
      "discharge": "parkCartAtPedestrianAisleMouth"
    }
  },
  {
    "id": "park_carts_only_in_clear_wide_places",
    "text": "A cart may only be left in a sufficiently wide, non-shelf-adjacent place where it will not block shoppers.",
    "abstraction": {
      "state_properties": {
        "clearCartParkingSpot": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "leaveCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leaveCart",
          {
            "not": "clearCartParkingSpot"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_roaming_outside_exempt_zones",
    "text": "Except at the entrance/cart bay and in the pedestrian-only aisle area, shoppers should not roam the store without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "entranceOrCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "pedestrianAisleMouth": "at(6,3)",
        "cartlessTravelPermitted": {
          "or": [
            "entranceOrCartBay",
            "pedestrianAisleMouth",
            "singleFileAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessTravelPermitted"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_cart_after_pedestrian_detour",
    "text": "After leaving a cart to enter a pedestrian-only aisle, the agent is obliged to reclaim the same cart at the aisle mouth before continuing.",
    "abstraction": {
      "state_properties": {
        "pedestrianAisleMouth": "at(6,3)"
      },
      "events": {
        "leaveCartForPedestrianAisle": {
          "pre": {
            "and": [
              "pedestrianAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "reclaimCartAtPedestrianAisleMouth": {
          "pre": {
            "and": [
              "pedestrianAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leaveCartForPedestrianAisle",
      "discharge": "reclaimCartAtPedestrianAisleMouth"
    }
  },
  {
    "id": "no_cart_shelf_interaction_in_pedestrian_aisle",
    "text": "Shelf interactions inside a single-file pedestrian aisle must be performed without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "pedestrianShelfAisle": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "pedestrianShelfAisle"
        ]
      }
    }
  }
]
